import sys, os, re, time, subprocess, json, hashlib, shutil; sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from dl import *
tee('c77')
purge()
HOME = os.path.expanduser('~')
cfg_before = hashlib.sha256(open(f'{HOME}/.docker/config.json', 'rb').read()).hexdigest()
def d(*a, env=None):
    e = dict(os.environ); e.pop('DOCKER_HOST', None); e.pop('DOCKER_CONTEXT', None); e.update(env or {})
    r = subprocess.run(['docker', *a], capture_output=True, text=True, timeout=60, env=e)
    return r.returncode, tidy(r.stdout + r.stderr)
SOCK = f'{HOME}/.docker/run/docker.sock'
print('== 一:docker context 是什么(Docker CLI,Docker Engine 29.8.2)')
rc, o = d('context', 'ls', '--format', '{{.Name}} 当前={{.Current}} 端点={{.DockerEndpoint}}')
for l in o.strip().splitlines(): print('  ' + l.replace(HOME, '~'))
cur = json.load(open(f'{HOME}/.docker/config.json')).get('currentContext')
print(f'  ~/.docker/config.json 里的 currentContext = {cur}')
name = 'desktop-linux'
h = hashlib.sha256(name.encode()).hexdigest()
print(f'  上下文存放在 ~/.docker/contexts/meta/<sha256(名字)>/meta.json:sha256("{name}") 的目录存在吗?{os.path.isdir(f"{HOME}/.docker/contexts/meta/{h}")}')
m = json.load(open(f'{HOME}/.docker/contexts/meta/{h}/meta.json')); print('  meta.json 的键:' + str(sorted(m.keys())) + ';Endpoints.docker.Host = ' + m['Endpoints']['docker']['Host'].replace(HOME, '~'))
print('== 二:建一个新的上下文,只用 --context / DOCKER_CONTEXT 临时使用(不执行 docker context use)')
rc, o = d('context', 'create', 'bwlab-c77', '--docker', f'host=unix://{SOCK}', '--description', 'c77 实验'); print(f'  docker context create bwlab-c77 --docker host=unix://~/.docker/run/docker.sock:退出码 {rc};{o.strip()[:70]}')
h2 = hashlib.sha256(b'bwlab-c77').hexdigest()
print(f'  新增了目录 ~/.docker/contexts/meta/{h2[:12]}…/:{os.path.isdir(f"{HOME}/.docker/contexts/meta/{h2}")};meta.json:' + json.dumps(json.load(open(f'{HOME}/.docker/contexts/meta/{h2}/meta.json')), ensure_ascii=False).replace(HOME, '~')[:200])
rc, o = d('--context', 'bwlab-c77', 'version', '--format', '{{.Server.Version}}'); print(f'  docker --context bwlab-c77 version:退出码 {rc};服务端版本 {o.strip()}')
rc, o = d('version', '--format', '{{.Server.Version}}', env={'DOCKER_CONTEXT': 'bwlab-c77'}); print(f'  DOCKER_CONTEXT=bwlab-c77 docker version:退出码 {rc};服务端版本 {o.strip()}')
print('  docker context ls 里的“当前”标记:' + d('context', 'ls', '--format', '{{.Name}}={{.Current}}')[1].strip().replace('\n', ' '))
print('== 三:优先级:-H / DOCKER_HOST / --context / DOCKER_CONTEXT / currentContext')
bad = 'unix:///nonexistent.sock'
for label, a, env in (('DOCKER_HOST 指向不存在的 socket', ['version', '--format', '{{.Server.Version}}'], {'DOCKER_HOST': bad}), ('DOCKER_HOST 无效,同时 --context bwlab-c77', ['--context', 'bwlab-c77', 'version', '--format', '{{.Server.Version}}'], {'DOCKER_HOST': bad}), ('DOCKER_HOST 无效,同时 DOCKER_CONTEXT=bwlab-c77', ['version', '--format', '{{.Server.Version}}'], {'DOCKER_HOST': bad, 'DOCKER_CONTEXT': 'bwlab-c77'}), ('-H 指向正确 socket,同时 DOCKER_HOST 无效', ['-H', f'unix://{SOCK}', 'version', '--format', '{{.Server.Version}}'], {'DOCKER_HOST': bad})):
    rc, o = d(*a, env=env); print(f'  {label}:退出码 {rc};{o.strip().splitlines()[-1][:110] if o.strip() else ""}')
rc, o = d('--context', 'bwlab-c77', '-H', f'unix://{SOCK}', 'version', '--format', '{{.Server.Version}}'); print(f'  同时给 --context 和 -H:退出码 {rc};{o.strip()[:110]}')
print('== 四:ssh 上下文的写法(只创建,不连接)与导出')
rc, o = d('context', 'create', 'bwlab-c77-ssh', '--docker', 'host=ssh://deploy@example.invalid:2222'); print(f'  docker context create … host=ssh://deploy@example.invalid:2222:退出码 {rc}')
rc, o = d('context', 'inspect', 'bwlab-c77-ssh', '--format', '{{json .Endpoints.docker}}'); print('  Endpoints.docker = ' + o.strip())
rc, o = d('--context', 'bwlab-c77-ssh', 'version', '--format', '{{.Server.Version}}'); print(f'  使用这个 ssh 上下文:退出码 {rc};{o.strip().splitlines()[-1][:130]}')
print('== 五:清理,并确认没有改动用户的 CLI 配置')
for c in ('bwlab-c77', 'bwlab-c77-ssh'): d('context', 'rm', '-f', c)
print('  删除后 docker context ls:' + d('context', 'ls', '--format', '{{.Name}}')[1].strip().replace('\n', ' '))
cfg_after = hashlib.sha256(open(f'{HOME}/.docker/config.json', 'rb').read()).hexdigest()
print(f'  ~/.docker/config.json 的哈希前后相同吗?{cfg_before == cfg_after};currentContext 仍是 {json.load(open(f"{HOME}/.docker/config.json")).get("currentContext")}')
print('  ~/.docker/contexts/meta 下的目录数:' + str(len(os.listdir(f'{HOME}/.docker/contexts/meta'))))
purge()
